 static Material ParticleMat(){string p=Data+"WashMist.mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(m==null){m=new Material(Shader.Find("Particles/Standard Unlit"));m.SetFloat("_Mode",2);m.SetInt("_SrcBlend",5);m.SetInt("_DstBlend",10);m.SetInt("_ZWrite",0);m.EnableKeyword("_ALPHABLEND_ON");m.renderQueue=3000;var tx=new Texture2D(32,32,TextureFormat.RGBA32,false);for(int y=0;y<32;y++)for(int x=0;x<32;x++){float d=Vector2.Distance(new Vector2(x+.5f,y+.5f),new Vector2(16,16))/16;tx.SetPixel(x,y,new Color(1,1,1,Mathf.Pow(Mathf.Clamp01(1-d*d),3)));}tx.Apply();AssetDatabase.CreateAsset(tx,Data+"WashMist.asset");m.mainTexture=tx;AssetDatabase.CreateAsset(m,p);}return m;}
